package org.slavicmyths.volkolak;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.tags.BiomeTags;
import org.slavicmyths.military.GreyWolfStory;
import org.slavicmyths.registry.*;

public final class VolkolakStory {
 public static String phase(ServerPlayer p){String value=GreyWolfStory.quest(p,3).getString("Phase");return value.isEmpty()?"TRACK":value;}
 public static VolkolakRecords.Encounter record(ServerPlayer p){var q=GreyWolfStory.quest(p,3);return q.hasUUID("Encounter")?VolkolakRecords.get(p.getServer().overworld()).encounters.get(q.getUUID("Encounter")):null;}
 private static boolean forest(ServerLevel w,BlockPos pos){var biome=w.getChunkSource().getGenerator().getBiomeSource().getNoiseBiome(pos.getX()>>2,16,pos.getZ()>>2,w.getChunkSource().randomState().sampler());return biome.is(BiomeTags.IS_FOREST)||biome.is(BiomeTags.IS_TAIGA);}
 public static BlockPos hint(BlockPos pos,long seed,int min,int max){var r=new Random(seed);double a=r.nextDouble()*Math.PI*2,d=min+r.nextDouble()*(max-min);return new BlockPos((int)Math.round((pos.getX()+Math.cos(a)*d)/20)*20,64,(int)Math.round((pos.getZ()+Math.sin(a)*d)/20)*20);}
 public static void ensure(ServerPlayer p,BlockPos wolf){if(p.level().dimension()!=Level.OVERWORLD||GreyWolfStory.stage(p,3)!=GreyWolfStory.Stage.ACTIVE)return;var w=p.serverLevel();var data=VolkolakRecords.get(w);var q=GreyWolfStory.quest(p,3);var e=record(p);
  if(e==null){UUID id=UUID.nameUUIDFromBytes((w.getSeed()+":"+wolf.asLong()).getBytes(StandardCharsets.UTF_8));e=data.encounters.get(id);if(e==null){if(data.encounters.size()>=4096)return;var r=new Random(w.getSeed()^wolf.asLong()^0x143L);for(int n=0;n<128;n++){double a=r.nextDouble()*Math.PI*2,d=720+r.nextDouble()*760;BlockPos candidate=wolf.offset((int)(Math.cos(a)*d),0,(int)(Math.sin(a)*d));if(!forest(w,candidate)||!w.getWorldBorder().isWithinBounds(candidate))continue;e=new VolkolakRecords.Encounter();e.id=id;e.wolf=wolf;e.anchor=new BlockPos(candidate.getX(),0,candidate.getZ());data.encounters.put(id,e);data.setDirty();break;}}if(e==null)return;q.putUUID("Encounter",e.id);q.putLong("Hint",hint(e.anchor,e.id.getLeastSignificantBits()^p.getUUID().getLeastSignificantBits(),130,230).asLong());q.putString("Phase",e.stage.equals("ESCAPED")||e.stage.equals("RESOLVED")?"FIND_CURSE":"TRACK");}
  if(e.stage.equals("ESCAPED")&&!e.cinematicDone&&w.getGameTime()>=e.escapedAt+150){e.cinematicDone=true;data.setDirty();}
  if(e.stage.equals("ESCAPED")||e.stage.equals("RESOLVED")){if(e.cinematicDone&&(phase(p).equals("FIGHT")||phase(p).equals("TRACK")))q.putString("Phase","FIND_CURSE");if(e.grave!=null){if(!phase(p).equals("RETURN"))q.putLong("Hint",hint(e.grave,e.id.getMostSignificantBits()^p.getUUID().getLeastSignificantBits(),65,105).asLong());placeGrave(w,e);if(q.getBoolean("Tracked")&&q.getLong("TrackedHint")!=q.getLong("Hint")){GreyWolfStory.track(p,3);q.putLong("TrackedHint",q.getLong("Hint"));}if(phase(p).equals("RETURN")&&!e.issues.containsKey(p.getUUID())){q.putString("Phase","EXCAVATE");q.putLong("Hint",hint(e.grave,e.id.getMostSignificantBits()^p.getUUID().getLeastSignificantBits(),65,105).asLong());}if(e.placed&&p.distanceToSqr(e.grave.getX()+.5,e.grave.getY(),e.grave.getZ()+.5)<=36&&w.hasChunkAt(e.grave)&&phase(p).equals("FIND_CURSE")){q.putString("Phase","EXCAVATE");GreyWolfStory.cue(p,"quest_progress");}if(e.placed&&p.distanceToSqr(e.grave.getX()+.5,e.grave.getY(),e.grave.getZ()+.5)<=49&&w.getGameTime()>=q.getLong("RustleAt")){q.putLong("RustleAt",w.getGameTime()+240+p.getRandom().nextInt(261));w.playSound(null,e.grave,VolkolakSounds.get("grave_rustle"),net.minecraft.sounds.SoundSource.BLOCKS,.25F,1);}}return;}
  if(e.boss!=null){if(w.getEntity(e.boss) instanceof CursedVolkolak boss&&p.distanceToSqr(boss)<=48*48&&boss.getTarget()==p){e.participants.put(p.getUUID(),w.getGameTime());data.setDirty();}if(e.stage.equals("FIGHT")&&w.getEntity(e.boss) instanceof CursedVolkolak boss&&p.distanceToSqr(boss)<=48*48)q.putString("Phase","FIGHT");return;}
  if(Math.hypot(p.getX()-e.anchor.getX(),p.getZ()-e.anchor.getZ())>160||!w.hasChunkAt(e.anchor))return;
  BlockPos spot=findArena(w,e);if(spot==null)return;e.anchor=spot;if(e.grave==null&&!reserveGrave(w,e)){data.setDirty();return;}
  var boss=ModEntities.CURSED_VOLKOLAK.get().create(w);if(boss==null)return;boss.encounter=e.id;boss.home=spot;boss.moveTo(spot.getX()+.5,spot.getY(),spot.getZ()+.5,0,0);if(!w.addFreshEntity(boss))return;e.anchor=spot;e.boss=boss.getUUID();e.stage="FIGHT";data.setDirty();
 }
 private static BlockPos findArena(ServerLevel w,VolkolakRecords.Encounter e){var rng=new Random(e.id.getLeastSignificantBits());for(int n=0;n<32;n++){BlockPos candidate=n==0?e.anchor:e.anchor.offset(rng.nextInt(49)-24,0,rng.nextInt(49)-24);double distance=Math.hypot(candidate.getX()-e.wolf.getX(),candidate.getZ()-e.wolf.getZ());if(distance<700||distance>1500)continue;var spot=surface(w,candidate);if(spot!=null&&safe(w,spot,4,3))return spot;}return null;}
 private static BlockPos surface(ServerLevel w,BlockPos pos){if(!w.hasChunkAt(pos))return null;return new BlockPos(pos.getX(),w.getHeight(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,pos.getX(),pos.getZ()),pos.getZ());}
 private static boolean earth(net.minecraft.world.level.block.state.BlockState s){return s.is(Blocks.DIRT)||s.is(Blocks.GRASS_BLOCK)||s.is(Blocks.PODZOL)||s.is(Blocks.COARSE_DIRT);}
 private static boolean safe(ServerLevel w,BlockPos air,int radius,int height){if(!w.getWorldBorder().isWithinBounds(air)||air.distSqr(w.getSharedSpawnPos())<128*128)return false;for(int x=-radius;x<=radius;x++)for(int z=-radius;z<=radius;z++){BlockPos b=air.offset(x,-1,z);if(!w.hasChunkAt(b)||!earth(w.getBlockState(b))||w.getBlockEntity(b)!=null)return false;for(int y=0;y<height;y++){BlockPos v=air.offset(x,y,z);if(!w.hasChunkAt(v)||!w.getBlockState(v).canBeReplaced()||!w.getFluidState(v).isEmpty()||w.getBlockEntity(v)!=null)return false;}}
  if(!org.slavicmyths.worldgen.ManualStructureRecords.get(w).overlapping(new net.minecraft.world.level.levelgen.structure.BoundingBox(air.getX()-100,w.getMinBuildHeight(),air.getZ()-100,air.getX()+100,w.getMaxBuildHeight(),air.getZ()+100)).isEmpty())return false;
  if(!w.getChunkAt(air).getAllReferences().isEmpty())return false;
  return w.getPoiManager().getInRange(h->h.is(net.minecraft.world.entity.ai.village.poi.PoiTypes.HOME),air,128,net.minecraft.world.entity.ai.village.poi.PoiManager.Occupancy.ANY).findAny().isEmpty();
 }
 /** Loaded natural soil, no recorded construction. Stable block states are checked again before adding vegetation. */
 private static boolean reserveGrave(ServerLevel w,VolkolakRecords.Encounter e){var r=new Random(e.id.getMostSignificantBits());for(int n=0;n<64;n++){double a=r.nextDouble()*Math.PI*2,d=90+r.nextDouble()*80;BlockPos xz=e.anchor.offset((int)(Math.cos(a)*d),0,(int)(Math.sin(a)*d));if(!w.hasChunkAt(xz)||!forest(w,xz)||VolkolakRecords.get(w).editedChunks.contains(ChunkPos.asLong(xz.getX()>>4,xz.getZ()>>4)))continue;var pos=surface(w,xz);if(pos==null||!safe(w,pos,2,2))continue;boolean ok=true;var terrain=new CompoundTag();for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)for(int y=-4;y<=0;y++){var b=pos.offset(x,y,z);if(w.getBlockEntity(b)!=null||(y==-1||x==0&&z==0&&y>=-3&&y<0)&&!earth(w.getBlockState(b))){ok=false;break;}terrain.put(x+":"+y+":"+z,NbtUtils.writeBlockState(w.getBlockState(b)));}if(!ok)continue;e.grave=pos;e.terrain=terrain;VolkolakRecords.get(w).setDirty();return true;}return false;}
 /** Never replaces any terrain block: the saved cache materialises only in the air excavated by players. */
 public static boolean placeGrave(ServerLevel w,VolkolakRecords.Encounter e){
  if(e.grave==null||!w.hasChunkAt(e.grave)||!e.stage.equals("ESCAPED")&&!e.stage.equals("RESOLVED"))return false;
  if(!e.placed){
   for(String key:e.terrain.getAllKeys()){String[] v=key.split(":");BlockPos b=e.grave.offset(Integer.parseInt(v[0]),Integer.parseInt(v[1]),Integer.parseInt(v[2]));if(!w.hasChunkAt(b)||w.getBlockEntity(b)!=null)return false;var original=NbtUtils.readBlockState(w.holderLookup(net.minecraft.core.registries.Registries.BLOCK),e.terrain.getCompound(key));var current=w.getBlockState(b);if(!current.equals(original)&&!(current.isAir()&&(earth(original)||original.canBeReplaced())))return false;}
   // Earlier excavation is legitimate. Never restore removed soil or replace a new construction.
   if(w.getBlockState(e.grave).isAir()&&earth(w.getBlockState(e.grave.below())))w.setBlock(e.grave,ModBlocks.PLACH_TRAVA.get().defaultBlockState(),3);
   e.placed=true;VolkolakRecords.get(w).setDirty();
  }
  BlockPos cache=e.grave.below(3);boolean exposed=true;for(int y=0;y<3;y++)if(!w.getBlockState(cache.above(y)).isAir())exposed=false;
  if(exposed&&w.getBlockEntity(cache)==null){w.setBlock(cache,ModBlocks.CURSED_SKULL_CACHE.get().defaultBlockState(),3);w.playSound(null,cache,VolkolakSounds.get("grave_dig"),net.minecraft.sounds.SoundSource.BLOCKS,.35F,1);}
  return true;
 }
 public static void escaped(CursedVolkolak boss){if(!(boss.level() instanceof ServerLevel w)||boss.encounter==null)return;var data=VolkolakRecords.get(w);var e=data.encounters.get(boss.encounter);if(e!=null&&boss.getUUID().equals(e.boss)){e.cinematicDone=true;data.setDirty();placeGrave(w,e);for(var entry:e.participants.entrySet()){var p=w.getServer().getPlayerList().getPlayer(entry.getKey());if(p!=null&&w.getGameTime()-entry.getValue()<=930&&p.level()==w&&p.distanceToSqr(boss)<=48*48&&record(p)==e&&GreyWolfStory.stage(p,3)==GreyWolfStory.Stage.ACTIVE){GreyWolfStory.quest(p,3).putString("Phase","FIND_CURSE");p.displayClientMessage(GreyWolfStory.text("volkolak_escaped"),false);org.slavicmyths.wolf.WolfStoryNetwork.changed(p);}}}}
 public static void lethal(CursedVolkolak boss){if(!(boss.level() instanceof ServerLevel w)||boss.encounter==null)return;var data=VolkolakRecords.get(w);var e=data.encounters.get(boss.encounter);if(e==null||!boss.getUUID().equals(e.boss)||!e.stage.equals("FIGHT"))return;e.participants.entrySet().removeIf(v->w.getGameTime()-v.getValue()>800);e.stage="ESCAPED";e.escapedAt=w.getGameTime();data.setDirty();boss.escape();}
 public static boolean cache(ServerPlayer p,BlockPos pos){if(p.level().dimension()!=Level.OVERWORLD||p.distanceToSqr(pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5)>25||GreyWolfStory.stage(p,3)!=GreyWolfStory.Stage.ACTIVE)return false;var e=record(p);if(e==null||e.grave==null||!e.placed||!pos.equals(e.grave.below(3))||!e.cinematicDone||e.issues.containsKey(p.getUUID())||e.returned.contains(p.getUUID()))return false;
  for(int y=1;y<=3;y++)if(!p.serverLevel().getBlockState(pos.above(y)).getCollisionShape(p.serverLevel(),pos.above(y)).isEmpty())return false;
  var clip=p.level().clip(new net.minecraft.world.level.ClipContext(p.getEyePosition(),pos.getCenter(),net.minecraft.world.level.ClipContext.Block.OUTLINE,net.minecraft.world.level.ClipContext.Fluid.NONE,p));if(!clip.getBlockPos().equals(pos))return false;
  UUID nonce=UUID.randomUUID();var skull=new ItemStack(ModItems.CURSED_VOLKOLAK_SKULL.get());var tag=new CompoundTag();tag.putUUID("Owner",p.getUUID());tag.putUUID("Encounter",e.id);tag.putUUID("Nonce",nonce);tag.putLong("Grave",e.grave.asLong());tag.putString("Dimension","minecraft:overworld");skull.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));var probe=new net.minecraft.world.entity.player.Inventory(p);for(int n=0;n<p.getInventory().getContainerSize();n++)probe.setItem(n,p.getInventory().getItem(n).copy());var remainder=skull.copy();probe.add(remainder);if(!remainder.isEmpty()){p.displayClientMessage(GreyWolfStory.text("inventory_full"),true);return false;}e.issues.put(p.getUUID(),nonce);VolkolakRecords.get(p.serverLevel()).setDirty();for(int n=0;n<p.getInventory().getContainerSize();n++)p.getInventory().setItem(n,probe.getItem(n));p.getInventory().setChanged();var q=GreyWolfStory.quest(p,3);q.putString("Phase","RETURN");p.displayClientMessage(GreyWolfStory.text("skull_collected"),false);q.putLong("Hint",e.wolf.asLong());p.playNotifySound(VolkolakSounds.get("skull_unearth"),net.minecraft.sounds.SoundSource.PLAYERS,.6F,1);org.slavicmyths.wolf.WolfStoryNetwork.changed(p);return true;
 }
 public static boolean handOver(ServerPlayer p){var e=record(p);if(e==null||!phase(p).equals("RETURN")||e.returned.contains(p.getUUID()))return false;UUID nonce=e.issues.get(p.getUUID());if(nonce==null)return false;for(int slot=0;slot<p.getInventory().getContainerSize();slot++){var item=p.getInventory().getItem(slot);if(!item.is(ModItems.CURSED_VOLKOLAK_SKULL.get()))continue;var tag=item.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag();if(!tag.hasUUID("Owner")||!tag.getUUID("Owner").equals(p.getUUID())||!tag.hasUUID("Encounter")||!tag.getUUID("Encounter").equals(e.id)||!tag.hasUUID("Nonce")||!tag.getUUID("Nonce").equals(nonce))continue;item.shrink(1);p.getInventory().setChanged();e.returned.add(p.getUUID());e.stage="RESOLVED";VolkolakRecords.get(p.getServer().overworld()).setDirty();var q=GreyWolfStory.quest(p,3);q.putBoolean("Discovered",true);q.putString("Phase","SKULL_RETURNED");GreyWolfStory.ready(p,3);p.playNotifySound(VolkolakSounds.get("curse_cleared"),net.minecraft.sounds.SoundSource.PLAYERS,.65F,1);return true;}return false;}
 private VolkolakStory(){}
}
